package com.franco.desco.adapter.in.web.salesoperation;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.salesoperation.*;import com.franco.desco.application.salesoperation.port.in.SalesOperationUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/operativos")@Tag(name="Operativos de venta",description="Planificación, zonas, recepción y cierre de operativos.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class SalesOperationController{private final SalesOperationUseCase u;private final SalesOperationWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public SalesOperationController(SalesOperationUseCase u,SalesOperationWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'OPERATIVOS_LISTAR')")@Operation(operationId="operativosListar",summary="Listar operativos")public ResponseEntity<ApiResponse<PageResponse<SalesOperationResponses.Summary>>>list(@RequestParam(required=false)Long campaniaVentaId,@RequestParam(required=false)String estadoProceso,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,campaniaVentaId,estadoProceso),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}")@PreAuthorize("@permissionGuard.has(authentication,'OPERATIVOS_VER')")@Operation(operationId="operativosVer",summary="Ver detalle del operativo")public ResponseEntity<ApiResponse<SalesOperationResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new SalesOperationCommands.Get(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'OPERATIVOS_CREAR')")@Operation(operationId="operativosCrear",summary="Crear operativo")public ResponseEntity<ApiResponse<SalesOperationResponses.Created>>create(@Valid@RequestBody SalesOperationRequests.Create q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.create(new SalesOperationCommands.Create(q.campaniaVentaId(),q.codigo(),q.fechaInicioProgramada(),q.fechaFinProgramada(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,SalesOperationResponses.Created::new);}
 @PutMapping("/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'OPERATIVOS_EDITAR')")@Operation(operationId="operativosEditar",summary="Editar operativo")public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody SalesOperationRequests.Update q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.update(new SalesOperationCommands.Update(id,q.fechaInicioProgramada(),q.fechaFinProgramada(),q.observacion()),ids.resolve(a),meta.resolve(r)),r);}
 @PutMapping("/{id}/zonas")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'OPERATIVOS_CREAR')")@Operation(operationId="operativosAsignarZonas",summary="Asignar zonas al operativo")public ResponseEntity<ApiResponse<Void>>zones(@PathVariable Long id,@Valid@RequestBody SalesOperationRequests.Zones q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.setZones(new SalesOperationCommands.SetZones(id,q.zonas()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/iniciar-recepcion")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'OPERATIVOS_CONFIRMAR')")@Operation(operationId="operativosIniciarRecepcion",summary="Iniciar recepción")public ResponseEntity<ApiResponse<Void>>start(@PathVariable Long id,@Valid@RequestBody SalesOperationRequests.Transition q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.startReception(new SalesOperationCommands.Transition(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/cerrar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'OPERATIVOS_CONFIRMAR') || @permissionGuard.has(authentication,'OPERATIVOS_APROBAR')")@Operation(operationId="operativosCerrar",summary="Cerrar operativo")public ResponseEntity<ApiResponse<Void>>close(@PathVariable Long id,@Valid@RequestBody SalesOperationRequests.Transition q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.close(new SalesOperationCommands.Transition(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/cancelar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'OPERATIVOS_RETIRAR')")@Operation(operationId="operativosCancelar",summary="Cancelar operativo")public ResponseEntity<ApiResponse<Void>>cancel(@PathVariable Long id,@Valid@RequestBody SalesOperationRequests.Transition q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.cancel(new SalesOperationCommands.Transition(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}}
